"""`make site-gen`: runs every generator and records the generated files in apps/site/.gitignore so they are never committed."""

from __future__ import annotations

import sys

from scripts.site import gen_proof, gen_reference, import_docs
from scripts.site.common import SITE

BEGIN = "# BEGIN generated by scripts/site/import_docs.py (do not edit)"
END = "# END generated"


def main() -> int:
    files = [*import_docs.run(), *gen_reference.run()]
    rel = sorted(f.relative_to(SITE).as_posix() for f in files)
    gi = SITE / ".gitignore"
    text = gi.read_text()
    head, _, rest = text.partition(BEGIN)
    old, _, tail = rest.partition(END)
    for line in old.splitlines():  # a page that is no longer generated must not linger
        stale = SITE / line.strip()
        if line.strip() and not line.startswith("#") and line.strip() not in rel and stale.is_file():
            stale.unlink()
    gi.write_text(head + BEGIN + "\n" + "\n".join(rel) + "\n" + END + tail)
    gen_proof.main()
    print(f"site-gen: {len(rel)} generated pages")
    return 0


if __name__ == "__main__":
    sys.exit(main())
